=== FILE: axil_timer.v ===
`timescale 1ns / 1ps
`default_nettype none

// axil_timer: 32-bit down-counting timer, one-shot and periodic modes, level
// interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ---------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------
  reg                  aw_held;
  reg                  w_held;
  reg [ADDR_WIDTH-1:0] awaddr_q;
  reg [31:0]           wdata_q;
  reg [3:0]            wstrb_q;

  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;

  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg                  expired_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;

  // ---------------------------------------------------------------------
  // Write channels
  // ---------------------------------------------------------------------
  wire awready_w = !aw_held && !bvalid_q;
  wire wready_w  = !w_held  && !bvalid_q;
  wire aw_hs     = s_axil_awvalid && awready_w;
  wire w_hs      = s_axil_wvalid  && wready_w;

  // Both halves present (held or arriving): the write takes effect now.
  wire do_write  = (aw_held || aw_hs) && (w_held || w_hs);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? awaddr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held  ? wdata_q  : s_axil_wdata;
  wire [3:0]            wr_strb = w_held  ? wstrb_q  : s_axil_wstrb;

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];
  wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

  wire wr_ctrl   = do_write && wr_mapped && (wr_idx == IDX_CTRL);
  wire wr_load   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
  wire wr_status = do_write && wr_mapped && (wr_idx == IDX_STATUS);

  // ---------------------------------------------------------------------
  // Read channel
  // ---------------------------------------------------------------------
  wire arready_w = !rvalid_q;
  wire ar_hs     = s_axil_arvalid && arready_w;

  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  reg [31:0] rd_val;
  always @(*) begin
    rd_val = 32'd0;
    if (rd_mapped) begin
      case (rd_idx)
        IDX_CTRL:   rd_val = {29'd0, mode_q, ie_q, en_q};
        IDX_LOAD:   rd_val = load_q;
        IDX_COUNT:  rd_val = count_q;
        IDX_STATUS: rd_val = {31'd0, expired_q};
        default:    rd_val = 32'd0;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Timer next state (priority by last assignment, microarchitecture 2)
  // ---------------------------------------------------------------------
  wire count_end = en_q && (count_q <= 32'd1);

  reg        en_d;
  reg        ie_d;
  reg        mode_d;
  reg        expired_d;
  reg [31:0] load_d;
  reg [31:0] count_d;

  always @(*) begin
    en_d      = en_q;
    ie_d      = ie_q;
    mode_d    = mode_q;
    expired_d = expired_q;
    load_d    = load_q;
    count_d   = count_q;

    // 1. Count step.
    if (count_end) begin
      if (mode_q) begin
        count_d = load_q;
      end else begin
        count_d = 32'd0;
        en_d    = 1'b0;
      end
    end else if (en_q) begin
      count_d = count_q - 32'd1;
    end

    // 2. EXPIRED: clear, then set; a count end beats a clear.
    if (wr_status && wr_strb[0] && wr_data[0]) begin
      expired_d = 1'b0;
    end
    if (count_end) begin
      expired_d = 1'b1;
    end

    // 3. CTRL write (byte 0 only); wins for en and count.
    if (wr_ctrl && wr_strb[0]) begin
      ie_d   = wr_data[1];
      mode_d = wr_data[2];
      if (wr_data[0]) begin
        en_d    = 1'b1;
        count_d = load_q;
      end else begin
        en_d    = 1'b0;
      end
    end

    // 4. LOAD write, byte merge.
    if (wr_load) begin
      if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
      if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
      if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
      if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
    end
  end

  // ---------------------------------------------------------------------
  // Registers (synchronous, active-low reset)
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      w_held    <= 1'b0;
      awaddr_q  <= {ADDR_WIDTH{1'b0}};
      wdata_q   <= 32'd0;
      wstrb_q   <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rdata_q   <= 32'd0;
      rresp_q   <= RESP_OKAY;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      expired_q <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
    end else begin
      // Write address holding
      if (do_write) begin
        aw_held <= 1'b0;
      end else if (aw_hs) begin
        aw_held <= 1'b1;
      end
      if (aw_hs) begin
        awaddr_q <= s_axil_awaddr;
      end

      // Write data holding
      if (do_write) begin
        w_held <= 1'b0;
      end else if (w_hs) begin
        w_held <= 1'b1;
      end
      if (w_hs) begin
        wdata_q <= s_axil_wdata;
        wstrb_q <= s_axil_wstrb;
      end

      // Write response
      if (do_write) begin
        bvalid_q <= 1'b1;
        bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
      end else if (bvalid_q && s_axil_bready) begin
        bvalid_q <= 1'b0;
      end

      // Read response
      if (ar_hs) begin
        rvalid_q <= 1'b1;
        rdata_q  <= rd_val;
        rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
      end else if (rvalid_q && s_axil_rready) begin
        rvalid_q <= 1'b0;
      end

      // Timer
      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      expired_q <= expired_d;
      load_q    <= load_d;
      count_q   <= count_d;
    end
  end

  // ---------------------------------------------------------------------
  // Outputs
  // ---------------------------------------------------------------------
  assign s_axil_awready = awready_w;
  assign s_axil_wready  = wready_w;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = arready_w;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired_q && ie_q;

`ifdef FORMAL
  // Design-intent assertions (not proven by any submitted job).
  reg f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!aresetn);
  end

  always @(*) begin
    if (f_past_valid) begin
      assert(!(aw_held && w_held));
      if (bvalid_q) assert(!aw_held && !w_held);
      assert(bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
      assert(rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
      if (!rvalid_q) assert(1'b1);
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(bvalid_q && !s_axil_bready)) begin
        assert(bvalid_q);
        assert(bresp_q == $past(bresp_q));
      end
      if ($past(rvalid_q && !s_axil_rready)) begin
        assert(rvalid_q);
        assert(rdata_q == $past(rdata_q));
        assert(rresp_q == $past(rresp_q));
      end
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axil_timer_tb.v ===
`timescale 1ns / 1ps

// Self-checking testbench for axil_timer.
// dut8: ADDR_WIDTH 8 (main checks). dut4: ADDR_WIDTH 4, driven with the low
// address bits and compared cycle by cycle with dut8 while 'lockstep' is set
// (cleared only while offsets from 0x10 up are exercised).
module axil_timer_tb;

  localparam [7:0] A_CTRL   = 8'h00;
  localparam [7:0] A_LOAD   = 8'h04;
  localparam [7:0] A_COUNT  = 8'h08;
  localparam [7:0] A_STATUS = 8'h0C;
  localparam [1:0] OKAY     = 2'b00;
  localparam [1:0] SLVERR   = 2'b10;

  reg        aclk    = 1'b0;
  reg        aresetn = 1'b0;
  reg  [7:0] awaddr  = 8'h00;
  reg        awvalid = 1'b0;
  reg [31:0] wdata   = 32'h0;
  reg  [3:0] wstrb   = 4'h0;
  reg        wvalid  = 1'b0;
  reg        bready  = 1'b0;
  reg  [7:0] araddr  = 8'h00;
  reg        arvalid = 1'b0;
  reg        rready  = 1'b0;

  wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
  wire  [1:0] bresp8, rresp8;
  wire [31:0] rdata8;
  wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire  [1:0] bresp4, rresp4;
  wire [31:0] rdata4;

  axil_timer #(.ADDR_WIDTH(8)) dut8 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready8),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready8),
    .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready8),
    .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready),
    .irq(irq8)
  );

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid), .s_axil_awready(awready4),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready),
    .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready),
    .irq(irq4)
  );

  always #5 aclk = ~aclk;

  // Rising-edge counter: after edge k (sampled 1 ns later) edge_n == k.
  integer edge_n = 0;
  always @(posedge aclk) edge_n <= edge_n + 1;

  // irq rise monitor (sampled at the falling edge; tagged with the edge
  // after which irq became high).
  integer irq_rises     = 0;
  integer irq_rise_edge = -1;
  reg     irq_prev      = 1'b0;
  always @(negedge aclk) begin
    if (irq8 && !irq_prev) begin
      irq_rises     <= irq_rises + 1;
      irq_rise_edge <= edge_n;
    end
    irq_prev <= irq8;
  end

  // ADDR_WIDTH 4 versus 8 lockstep comparison.
  reg     lockstep  = 1'b1;
  integer ls_cycles = 0;
  integer ls_fail   = 0;
  always @(negedge aclk) begin
    if (lockstep) begin
      ls_cycles <= ls_cycles + 1;
      if ({awready4, wready4, bvalid4, bresp4, arready4, rvalid4, rdata4, rresp4, irq4} !==
          {awready8, wready8, bvalid8, bresp8, arready8, rvalid8, rdata8, rresp8, irq8}) begin
        ls_fail <= ls_fail + 1;
        $error("ADDR_WIDTH 4 and 8 instances disagree after edge %0d", edge_n);
      end
    end
  end

  integer passed = 0;
  integer failed = 0;
  integer last_wr_edge = 0;
  integer last_rd_edge = 0;
  reg [31:0] rd_d;
  reg  [1:0] rd_r;
  reg [8*64-1:0] nonce;

  // -------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------
  task tick;
    begin
      @(posedge aclk);
      #1;
    end
  endtask

  task check(input ok, input integer id);
    begin
      if (ok) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed after edge %0d", id, edge_n);
      end
    end
  endtask

  task check32(input [31:0] got, input [31:0] expv, input integer id);
    begin
      if (got === expv) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed after edge %0d: got 0x%08h, expected 0x%08h",
               id, edge_n, got, expv);
      end
    end
  endtask

  task wait_edge(input integer n);
    begin
      while (edge_n < n) tick;
    end
  endtask

  task wait_rise(input integer base, input integer timeout, input integer id);
    integer g;
    begin
      g = 0;
      while (irq_rises == base && g < timeout) begin
        tick;
        g = g + 1;
      end
      check(irq_rises != base, id);
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first.
  // bdelay: cycles BREADY is held low while BVALID is high.
  task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                 input integer order, input integer bdelay,
                 input [1:0] exp_resp, input integer id);
    integer guard;
    integer k;
    reg aw_done, w_done, aw_fire, w_fire;
    reg [1:0] resp0;
    begin
      awaddr  = addr;
      wdata   = data;
      wstrb   = strb;
      aw_done = 1'b0;
      w_done  = 1'b0;
      guard   = 0;
      awvalid = (order != 2);
      wvalid  = (order != 1);
      while (!(aw_done && w_done) && guard < 50) begin
        aw_fire = awvalid && awready8;
        w_fire  = wvalid  && wready8;
        tick;
        guard = guard + 1;
        if (aw_fire) begin
          awvalid = 1'b0;
          aw_done = 1'b1;
        end
        if (w_fire) begin
          wvalid = 1'b0;
          w_done = 1'b1;
        end
        if (aw_done && !w_done) begin
          if (aw_fire) check(!awready8 && wready8 && !bvalid8, id);
          if (!wvalid) wvalid = 1'b1;
        end
        if (w_done && !aw_done) begin
          if (w_fire) check(!wready8 && awready8 && !bvalid8, id);
          if (!awvalid) awvalid = 1'b1;
        end
      end
      check(aw_done && w_done, id);
      last_wr_edge = edge_n;
      check(bvalid8, id);
      check(bresp8 == exp_resp, id);
      resp0 = bresp8;
      for (k = 0; k < bdelay; k = k + 1) begin
        check(bvalid8 && (bresp8 == resp0) && !awready8 && !wready8, id);
        tick;
      end
      bready = 1'b1;
      check(bvalid8, id);
      tick;
      bready = 1'b0;
      check(!bvalid8, id);
    end
  endtask

  // rdelay: cycles RREADY is held low while RVALID is high.
  task axi_read(input [7:0] addr, input integer rdelay,
                output [31:0] data, output [1:0] resp);
    integer guard;
    integer k;
    reg done, f;
    reg [31:0] d0;
    reg  [1:0] r0;
    begin
      araddr  = addr;
      arvalid = 1'b1;
      done    = 1'b0;
      guard   = 0;
      while (!done && guard < 50) begin
        f = arready8;
        tick;
        guard = guard + 1;
        if (f) done = 1'b1;
      end
      arvalid = 1'b0;
      last_rd_edge = edge_n;
      check(done && rvalid8, 900);
      d0 = rdata8;
      r0 = rresp8;
      for (k = 0; k < rdelay; k = k + 1) begin
        check(rvalid8 && (rdata8 === d0) && (rresp8 == r0) && !arready8, 901);
        tick;
      end
      rready = 1'b1;
      tick;
      rready = 1'b0;
      check(!rvalid8, 902);
      data = d0;
      resp = r0;
    end
  endtask

  task rd_check(input [7:0] addr, input [31:0] expv, input [1:0] exp_resp,
                input integer id);
    begin
      axi_read(addr, 0, rd_d, rd_r);
      check32(rd_d, expv, id);
      check(rd_r == exp_resp, id);
    end
  endtask

  task finish_sim;
    begin
      nonce = 512'd0;
      if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = 512'd0;
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
      $finish;
    end
  endtask

  // -------------------------------------------------------------------
  // Directed sequence
  // -------------------------------------------------------------------
  integer e0, e1, e2, s_edge, mk;
  reg [31:0] exp_v;

  initial begin
    // ---- Reset values ----
    aresetn = 1'b0;
    repeat (3) tick;
    check(!bvalid8 && !rvalid8 && !irq8, 1);
    check(awready8 && wready8 && arready8, 2);
    aresetn = 1'b1;
    tick;
    rd_check(A_CTRL,   32'd0, OKAY, 3);
    rd_check(A_LOAD,   32'd0, OKAY, 4);
    rd_check(A_COUNT,  32'd0, OKAY, 5);
    rd_check(A_STATUS, 32'd0, OKAY, 6);

    // ---- LOAD with partial strobes ----
    axi_write(A_LOAD, 32'hFFFFFFFF, 4'hF, 0, 0, OKAY, 10);
    rd_check(A_LOAD, 32'hFFFFFFFF, OKAY, 11);
    axi_write(A_LOAD, 32'h12345678, 4'h1, 0, 0, OKAY, 12);
    rd_check(A_LOAD, 32'hFFFFFF78, OKAY, 13);
    axi_write(A_LOAD, 32'hAABBCCDD, 4'h6, 0, 0, OKAY, 14);
    rd_check(A_LOAD, 32'hFFBBCC78, OKAY, 15);
    axi_write(A_LOAD, 32'h00000000, 4'h0, 0, 0, OKAY, 16);
    rd_check(A_LOAD, 32'hFFBBCC78, OKAY, 17);
    axi_write(A_LOAD, 32'h01000000, 4'h8, 0, 0, OKAY, 18);
    rd_check(A_LOAD, 32'h01BBCC78, OKAY, 19);

    // ---- Channel orders and back-pressure ----
    axi_write(A_LOAD, 32'hA5A50001, 4'hF, 1, 3, OKAY, 20);
    axi_read(A_LOAD, 4, rd_d, rd_r);
    check32(rd_d, 32'hA5A50001, 21);
    check(rd_r == OKAY, 22);
    axi_write(A_LOAD, 32'h5A5A0002, 4'hF, 2, 0, OKAY, 23);
    rd_check(A_LOAD, 32'h5A5A0002, OKAY, 24);
    axi_write(A_LOAD, 32'h00000003, 4'hF, 0, 5, OKAY, 25);
    rd_check(A_LOAD, 32'h00000003, OKAY, 26);

    // ---- Misaligned addresses: SLVERR, no change ----
    axi_write(8'h05, 32'hDEADBEEF, 4'hF, 0, 0, SLVERR, 30);
    rd_check(A_LOAD, 32'h00000003, OKAY, 31);
    axi_write(8'h01, 32'h00000007, 4'hF, 0, 0, SLVERR, 32);
    rd_check(A_CTRL, 32'd0, OKAY, 33);
    rd_check(8'h06, 32'd0, SLVERR, 34);
    rd_check(8'h0D, 32'd0, SLVERR, 35);

    // ---- CTRL write without wstrb[0] ----
    axi_write(A_LOAD, 32'd5, 4'hF, 0, 0, OKAY, 39);
    axi_write(A_CTRL, 32'h00000007, 4'hE, 0, 0, OKAY, 40);
    rd_check(A_CTRL, 32'd0, OKAY, 41);
    repeat (10) tick;
    rd_check(A_COUNT, 32'd0, OKAY, 42);
    check(!irq8 && (irq_rises == 0), 43);

    // ---- One-shot, LOAD 5, timed to the cycle ----
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 50);
    e0 = last_wr_edge;
    wait_rise(mk, 40, 51);
    check(irq_rise_edge == e0 + 5, 52);
    rd_check(A_CTRL,   32'h00000002, OKAY, 53);   // EN cleared itself
    rd_check(A_COUNT,  32'd0,        OKAY, 54);
    rd_check(A_STATUS, 32'd1,        OKAY, 55);
    axi_write(A_STATUS, 32'h00000000, 4'hF, 0, 0, OKAY, 56);  // writing 0 keeps it
    check(irq8, 57);
    axi_write(A_STATUS, 32'h00000001, 4'hE, 0, 0, OKAY, 58);  // no wstrb[0] keeps it
    check(irq8, 59);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 60);  // W1C
    check(!irq8, 61);
    rd_check(A_STATUS, 32'd0, OKAY, 62);
    mk = irq_rises;
    repeat (30) tick;
    check((irq_rises == mk) && !irq8, 63);           // no second interrupt
    rd_check(A_STATUS, 32'd0, OKAY, 64);

    // ---- COUNT value mid-count, LOAD 20 ----
    axi_write(A_LOAD, 32'd20, 4'hF, 0, 0, OKAY, 70);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 71);
    e0 = last_wr_edge;
    axi_read(A_COUNT, 0, rd_d, rd_r);
    exp_v = 20 - (last_rd_edge - 1 - e0);
    check32(rd_d, exp_v, 72);
    wait_rise(mk, 60, 73);
    check(irq_rise_edge == e0 + 20, 74);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 75);
    check(!irq8, 76);

    // ---- LOAD 1 and LOAD 0: one-cycle counts ----
    axi_write(A_LOAD, 32'd1, 4'hF, 0, 0, OKAY, 80);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 81);
    e0 = last_wr_edge;
    wait_rise(mk, 20, 82);
    check(irq_rise_edge == e0 + 1, 83);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 84);
    axi_write(A_LOAD, 32'd0, 4'hF, 0, 0, OKAY, 85);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 86);
    e0 = last_wr_edge;
    wait_rise(mk, 20, 87);
    check(irq_rise_edge == e0 + 1, 88);
    rd_check(A_COUNT, 32'd0, OKAY, 89);
    rd_check(A_CTRL, 32'h00000002, OKAY, 90);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 91);

    // ---- Interrupt enable on a pending expiry ----
    axi_write(A_LOAD, 32'd3, 4'hF, 0, 0, OKAY, 100);
    axi_write(A_CTRL, 32'h00000001, 4'h1, 0, 0, OKAY, 101);   // EN, IE 0
    repeat (10) tick;
    check(!irq8, 102);
    rd_check(A_STATUS, 32'd1, OKAY, 103);
    rd_check(A_CTRL,   32'd0, OKAY, 104);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000002, 4'h1, 0, 0, OKAY, 105);   // IE 1
    check((irq_rises == mk + 1) && (irq_rise_edge == last_wr_edge), 106);
    check(irq8, 107);
    axi_write(A_CTRL, 32'h00000000, 4'h1, 0, 0, OKAY, 108);
    check(!irq8, 109);
    axi_write(A_CTRL, 32'h00000002, 4'h1, 0, 0, OKAY, 110);
    check(irq8, 111);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 112);
    check(!irq8, 113);

    // ---- Periodic, LOAD 10, several periods ----
    axi_write(A_LOAD, 32'd10, 4'hF, 0, 0, OKAY, 120);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000007, 4'h1, 0, 0, OKAY, 121);
    e0 = last_wr_edge;
    wait_rise(mk, 40, 122);
    check(irq_rise_edge == e0 + 10, 123);
    rd_check(A_CTRL, 32'h00000007, OKAY, 124);                // EN stays 1
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 125);
    check(!irq8, 126);
    mk = irq_rises;
    wait_rise(mk, 40, 127);
    check(irq_rise_edge == e0 + 20, 128);
    // Acknowledge on the very edge the next count ends: expiry is kept.
    wait_edge(e0 + 29);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 129);
    check(last_wr_edge == e0 + 30, 130);
    rd_check(A_STATUS, 32'd1, OKAY, 131);
    check(irq8, 132);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 133);
    check(!irq8, 134);
    mk = irq_rises;
    wait_rise(mk, 40, 135);
    check(irq_rise_edge == e0 + 40, 136);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 137);

    // ---- Stop freezes COUNT ----
    axi_write(A_CTRL, 32'h00000006, 4'h1, 0, 0, OKAY, 138);   // EN 0
    s_edge = last_wr_edge;
    check((s_edge - (e0 + 40) >= 1) && (s_edge - (e0 + 40) <= 9), 139);
    exp_v = 10 - (s_edge - (e0 + 40));
    rd_check(A_CTRL, 32'h00000006, OKAY, 140);
    mk = irq_rises;
    repeat (25) tick;
    rd_check(A_COUNT, exp_v, OKAY, 141);
    check((irq_rises == mk) && !irq8, 142);

    // ---- COUNT is read only ----
    axi_write(A_COUNT, 32'h00000055, 4'hF, 0, 0, SLVERR, 143);
    rd_check(A_COUNT, exp_v, OKAY, 144);
    axi_write(A_COUNT, 32'h00000000, 4'h0, 0, 0, SLVERR, 145);
    rd_check(A_COUNT, exp_v, OKAY, 146);

    // ---- Restart while counting ----
    axi_write(A_LOAD, 32'd10, 4'hF, 0, 0, OKAY, 150);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 151);
    e1 = last_wr_edge;
    wait_edge(e1 + 5);
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 152);
    e2 = last_wr_edge;
    wait_rise(mk, 40, 153);
    check(irq_rise_edge == e2 + 10, 154);
    check(irq_rises == mk + 1, 155);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 156);
    mk = irq_rises;
    repeat (20) tick;
    check((irq_rises == mk) && !irq8, 157);

    // ---- CTRL write on a count end: EN 1 restarts (one-shot) ----
    axi_write(A_LOAD, 32'd6, 4'hF, 0, 0, OKAY, 160);
    mk = irq_rises;
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 161);
    e0 = last_wr_edge;
    wait_edge(e0 + 5);
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 162);
    check(last_wr_edge == e0 + 6, 163);
    wait_rise(mk, 20, 164);
    check(irq_rise_edge == e0 + 6, 165);
    rd_check(A_CTRL, 32'h00000003, OKAY, 166);                // EN still 1
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 167);
    mk = irq_rises;
    wait_rise(mk, 20, 168);
    check(irq_rise_edge == e0 + 12, 169);
    rd_check(A_CTRL, 32'h00000002, OKAY, 170);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 171);

    // ---- CTRL write on a count end: EN 0 stops (periodic) ----
    axi_write(A_LOAD, 32'd5, 4'hF, 0, 0, OKAY, 172);
    axi_write(A_CTRL, 32'h00000007, 4'h1, 0, 0, OKAY, 173);
    e0 = last_wr_edge;
    wait_edge(e0 + 4);
    axi_write(A_CTRL, 32'h00000006, 4'h1, 0, 0, OKAY, 174);
    check(last_wr_edge == e0 + 5, 175);
    check(irq8, 176);                                          // expiry still set
    rd_check(A_COUNT,  32'd5,        OKAY, 177);               // value the end gave
    rd_check(A_CTRL,   32'h00000006, OKAY, 178);
    rd_check(A_STATUS, 32'd1,        OKAY, 179);
    axi_write(A_STATUS, 32'h00000001, 4'h1, 0, 0, OKAY, 180);
    repeat (15) tick;
    rd_check(A_COUNT, 32'd5, OKAY, 181);
    check(!irq8, 182);

    // ---- End of the lockstep section ----
    check((ls_fail == 0) && (ls_cycles > 100), 190);
    lockstep = 1'b0;

    // ---- Offsets from 0x10 up at ADDR_WIDTH 8: SLVERR, no alias ----
    axi_write(8'h14, 32'h0000CAFE, 4'hF, 0, 0, SLVERR, 200);
    rd_check(A_LOAD, 32'd5, OKAY, 201);
    axi_write(8'h10, 32'h00000001, 4'hF, 0, 0, SLVERR, 202);
    rd_check(A_CTRL, 32'h00000006, OKAY, 203);
    axi_write(8'h1C, 32'h00000001, 4'hF, 0, 0, SLVERR, 204);
    axi_write(8'hFC, 32'h00000001, 4'hF, 0, 0, SLVERR, 205);
    axi_write(8'h80, 32'h00000000, 4'hF, 0, 0, SLVERR, 206);
    rd_check(A_CTRL, 32'h00000006, OKAY, 207);
    rd_check(8'h10, 32'd0, SLVERR, 208);
    rd_check(8'h14, 32'd0, SLVERR, 209);
    rd_check(8'h18, 32'd0, SLVERR, 210);
    rd_check(8'h1C, 32'd0, SLVERR, 211);
    rd_check(8'hF4, 32'd0, SLVERR, 212);
    rd_check(8'h84, 32'd0, SLVERR, 213);
    repeat (10) tick;
    rd_check(A_COUNT, 32'd5, OKAY, 214);
    check(!irq8, 215);

    // ---- Reset both instances, resume lockstep ----
    aresetn = 1'b0;
    tick;
    tick;
    lockstep = 1'b1;
    aresetn = 1'b1;
    tick;
    rd_check(A_CTRL, 32'd0, OKAY, 220);
    rd_check(A_LOAD, 32'd0, OKAY, 221);

    // ---- Reset during a count and during traffic ----
    axi_write(A_LOAD, 32'd100, 4'hF, 0, 0, OKAY, 222);
    axi_write(A_CTRL, 32'h00000003, 4'h1, 0, 0, OKAY, 223);
    repeat (10) tick;
    araddr  = A_COUNT;
    arvalid = 1'b1;
    check(arready8, 224);
    tick;
    arvalid = 1'b0;
    check(rvalid8, 225);                                       // response left waiting
    awaddr  = A_CTRL;
    wdata   = 32'h00000000;
    wstrb   = 4'hF;
    awvalid = 1'b1;
    check(awready8, 226);
    tick;
    awvalid = 1'b0;
    check(!awready8 && wready8 && !bvalid8, 227);              // address held alone
    aresetn = 1'b0;
    tick;
    tick;
    check(!rvalid8 && !bvalid8 && !irq8, 228);
    check(awready8 && wready8 && arready8, 229);
    aresetn = 1'b1;
    tick;
    rd_check(A_CTRL,   32'd0, OKAY, 230);
    rd_check(A_LOAD,   32'd0, OKAY, 231);
    rd_check(A_COUNT,  32'd0, OKAY, 232);
    rd_check(A_STATUS, 32'd0, OKAY, 233);
    // The held address was dropped: a lone W must wait for a new AW.
    wdata  = 32'h00000003;
    wstrb  = 4'hF;
    wvalid = 1'b1;
    check(wready8, 234);
    tick;
    wvalid = 1'b0;
    check(!bvalid8 && !wready8 && awready8, 235);
    repeat (3) tick;
    check(!bvalid8, 236);
    awaddr  = A_LOAD;
    awvalid = 1'b1;
    tick;
    awvalid = 1'b0;
    check(bvalid8 && (bresp8 == OKAY), 237);
    bready = 1'b1;
    tick;
    bready = 1'b0;
    check(!bvalid8, 237);
    rd_check(A_LOAD, 32'd3, OKAY, 238);
    mk = irq_rises;
    repeat (120) tick;
    check((irq_rises == mk) && !irq8, 239);                    // the count was stopped

    check((ls_fail == 0) && (ls_cycles > 0), 240);

    finish_sim;
  end

endmodule
